import {beginHoopStroke,trackHoopSegment,resetHoopProgress} from './scoring.js';
export const SIX=[[-7,10.5],[-7,-10.5],[7,-10.5],[7,10.5],[0,7],[0,-7]];
export const GOLF_ROUTE=[{h:0,d:-1},{h:1,d:-1},{h:2,d:1},{h:3,d:1},{h:4,d:-1},{h:5,d:-1},{h:1,d:1},{h:0,d:1},{h:3,d:-1},{h:2,d:-1},{h:5,d:1},{h:4,d:1},{h:2,d:1}];
const NINE=[[0,14],[0,12],[-9,6],[9,6],[0,0],[-9,-6],[9,-6],[0,-12],[0,-14]];
const h=(i,d)=>({h:i,d});
export const VARIANTS={
 golf:{name:'Golf Croquet',short:'GOLF',hoops:SIX,route:GOLF_ROUTE,stakes:[{x:0,z:0,id:'peg'}],goal:7,summary:'One stroke per turn. All balls contest the same hoop; first side to seven wins.',details:'Blue–Red–Black–Yellow. No bonus shots. A knocked-through ball scores for its owner. A tied match goes to hoop 3 for the deciding point.',limit:'Offside, jump shots and referee fault adjudication are not simulated.',url:'https://worldcroquet.org/croquet-information/golf-croquet/how-to-play-golf-croquet/'},
 association:{name:'Association Croquet',short:'ASSOCIATION',hoops:SIX,route:[...GOLF_ROUTE.slice(0,12),{stake:'peg'}],stakes:[{x:0,z:0,id:'peg'}],goal:26,summary:'Build a break: earn continuation strokes at hoops and take croquet after hitting a live ball.',details:'Each ball runs 12 hoops, then hits the centre peg. Both balls must finish to win (26 points). After the opening four turns, choose either ball of your side at the start of a turn. A hoop earns one continuation; a live-ball hit earns a contact croquet stroke, then one continuation. Use the contact-position slider to place your ball around the roqueted ball; both balls must move in the croquet shot. You may roquet each ball once per turn, refreshed by scoring your next hoop. A peeled ball scores for its owner without awarding a continuation to the striker.',limit:'Club rules: fixed opening positions on the baulk line, automated contact placement and fault replacement. No advanced lifts, wiring lifts, handicaps or full tournament fault adjudication.',url:'https://worldcroquet.org/croquet-information/association-croquet/how-to-play-association-croquet/'},
 nine:{name:'Nine-Wicket Backyard',short:'NINE-WICKET',hoops:NINE,route:[h(0,-1),h(1,-1),h(3,-1),h(4,-1),h(6,-1),h(7,-1),h(8,-1),{stake:'turning'},h(8,1),h(7,1),h(5,1),h(4,1),h(2,1),h(1,1),h(0,1),{stake:'finish'}],stakes:[{x:0,z:-16,id:'turning'},{x:0,z:16,id:'finish'}],goal:32,summary:'The backyard double diamond: run the course, hit the turning stake, and race home.',details:'Blue–Red–Black–Yellow. Each ball scores 14 wickets and two stakes (16 points); both balls must finish to win (32 points). A wicket or turning stake earns one bonus shot; two points in one shot earn two. Hitting a live ball earns two shots from where you lie (one of the USCA backyard options). Bonuses replace, rather than stack with, remaining shots. The first of a wicket or roquet takes precedence. A ball is live again next turn or after you score. Finished balls leave play.',limit:'Backyard rules: two roquet bonus shots from the lie; no foot shots or contact repositioning, carry-over deadness, poison or timed games. The double diamond is fitted to this lawn.',url:'https://croquetamerica.com/content.aspx?module_id=782355&page_id=22'}
};
export class VariantMatch{
 constructor(kind,balls){this.kind=kind;this.config=VARIANTS[kind];this.balls=balls;this.turn=0;this.opening=0;this.strokes=1;this.dead=new Set();this.croquetTarget=null;this.chooseBall=false;this.winner=null;this.message='Blue plays first.';for(const b of balls){b.progress=0;b.finished=false;resetHoopProgress(b)}}
 target(i=this.turn,step=this.balls[i].progress){const c=this.config,s=c.route[Math.min(step,c.route.length-1)];if(s.stake){const p=c.stakes.find(p=>p.id===s.stake);return {...p,stake:s.stake,key:step,direction:1,d:1,h:-1}}const [x,z]=c.hoops[s.h];return {x,z,h:s.h,direction:s.d,d:s.d,key:step}}
 scores(){return [0,1].map(side=>this.balls.filter(b=>b.side===side).reduce((n,b)=>n+b.progress,0))}
 startPosition(){return this.kind==='nine'?{x:0,z:15}:{x:-10+this.turn*.65,z:16.5}}
 selectBall(i){if(!this.chooseBall||this.balls[i].finished||this.balls[i].side!==this.balls[this.turn].side)return false;this.turn=i;return true}
 beginStroke(){this.chooseBall=false;this.wasCroquet=this.croquetTarget!==null;this.croquetBall=this.croquetTarget;this.snapshot=this.balls.map(b=>({x:b.x,z:b.z,progress:b.progress,hoopRun:b.hoopRun?{...b.hoopRun}:undefined}));this.strokes=Math.max(0,this.strokes-1);this.roquet=null;this.firstEvent=null;this.ticks=0;this.out=new Set();this.moved=new Set();this.scored=[];this.trials=this.balls.map((b,i)=>({step:b.progress,rows:[],active:{x:b.x,z:b.z,hoopRun:b.hoopRun?{...b.hoopRun}:undefined},i}));for(const t of this.trials){if(!this.target(t.i,t.step).stake)beginHoopStroke(t.active,this.target(t.i,t.step))}}
 recordContact(a,b){if(a!==this.turn&&b!==this.turn)return;const other=a===this.turn?b:a;if(this.roquet!==null||this.dead.has(other)||this.balls[other].finished||!this.balls[other].entered)return;if(this.kind==='nine'&&this.firstEvent==='point')return;this.roquet=other;this.firstEvent??='roquet';this.dead.add(other)}
 recordOut(i){this.out.add(i)}
 recordStake(i,id){const t=this.trials?.[i];if(!t||t.step>=this.config.route.length||this.target(i,t.step).stake!==id)return;if(i===this.turn&&this.roquet!==null)return;this.recordPoint(t,{stake:id,valid:true})}
 recordPoint(t,row){t.rows.push({step:t.step,...row});t.step++;this.scored.push(t.i);if(t.i===this.turn){this.firstEvent??='point';this.dead.clear()}const b=this.balls[t.i];t.active={x:b.x,z:b.z};if(t.step<this.config.route.length&&!this.target(t.i,t.step).stake)beginHoopStroke(t.active,this.target(t.i,t.step))}
 track(previous){this.ticks++;for(const t of this.trials){const b=this.balls[t.i];if(!b.entered||b.finished)continue;if(Math.hypot(b.x-previous[t.i].x,b.z-previous[t.i].z)>.00001)this.moved.add(t.i);
 for(const row of t.rows){if(row.tracker){row.tracker.x=b.x;row.tracker.z=b.z;trackHoopSegment(row.tracker,previous[t.i],row.hoop);row.valid=row.tracker.candidate}}
 if(t.step>=this.config.route.length)continue;if(t.i===this.turn&&this.roquet!==null)continue;const target=this.target(t.i,t.step);if(target.stake)continue;t.active.x=b.x;t.active.z=b.z;trackHoopSegment(t.active,previous[t.i],target);if(t.active.candidate){const tracker=t.active;this.recordPoint(t,{tracker,hoop:target,valid:true})}}
 }
 finishStroke(){let fault=false;if(this.kind==='association'&&this.wasCroquet){fault=!this.moved.has(this.croquetBall)||this.out.has(this.croquetBall);if(fault){this.balls.forEach((b,i)=>{Object.assign(b,this.snapshot[i])});this.message='Croquet fault: the other ball must move and stay on the lawn. Balls replaced; turn ends.';this.roquet=null;this.strokes=0}}
 const ownBefore=this.balls[this.turn].progress;let ownPoints=0;if(!fault)for(const t of this.trials){const b=this.balls[t.i];let step=b.progress;for(const row of t.rows){if(row.step!==step||!row.valid)break;step++}ownPoints+=t.i===this.turn?step-b.progress:0;b.progress=step;b.finished=step===this.config.route.length;const relevant=t.rows.find(row=>row.step===step&&row.tracker)?.tracker||(step===t.step?t.active:null);if(relevant?.hoopRun)b.hoopRun={...relevant.hoopRun};else if(step!==this.snapshot[t.i].progress)resetHoopProgress(b)}
 if(this.balls.filter(b=>b.side===this.balls[this.turn].side).every(b=>b.finished)){this.winner=this.balls[this.turn].side;return {over:true,scores:this.scores()}}
 // A peeled opponent can also complete that side's game.
 for(const side of [0,1])if(this.balls.filter(b=>b.side===side).every(b=>b.finished)){this.winner=side;return {over:true,scores:this.scores()}}
 this.croquetTarget=null;if(!fault){if(this.roquet!==null){if(this.kind==='association'){this.croquetTarget=this.roquet;this.strokes=1;this.message='Roquet! Place your ball in contact for a croquet shot.'}else{this.strokes=2;this.message='Roquet! Two bonus shots from the lie.'}}else if(ownPoints){this.strokes=this.kind==='nine'?Math.min(2,ownPoints):1;this.dead.clear();this.message=ownPoints+' point'+(ownPoints>1?'s':'')+' scored. '+this.strokes+' continuation shot'+(this.strokes>1?'s':'')+'.'}else if(this.wasCroquet){this.strokes=this.out.has(this.turn)?0:1;this.message='Croquet complete. One continuation shot.'}else if(this.strokes)this.message='One bonus shot remains.';else this.message='Turn complete.'}
 const continued=this.strokes>0&&!this.balls[this.turn].finished;if(!continued)this.nextTurn();this.measureIn(continued);return {over:false,continued,scores:this.scores(),fault}}
 nextTurn(){const side=this.balls[this.turn].side;this.opening++;this.strokes=1;this.dead.clear();this.croquetTarget=null;if(this.kind==='association'&&this.opening>=4){this.turn=this.balls.findIndex(b=>b.side!==side&&!b.finished);this.chooseBall=true}else{do{this.turn=(this.turn+1)%4}while(this.balls[this.turn].finished);this.chooseBall=false}}
 measureIn(continued){for(let i=0;i<4;i++){const b=this.balls[i];if(!b.entered||b.finished)continue;if(i===this.turn&&continued&&!this.out.has(i))continue;b.x=Math.max(-13,Math.min(13,b.x));b.z=Math.max(-16.5,Math.min(16.5,b.z))}}
 placeCroquet(angle){if(this.croquetTarget===null)return true;const b=this.balls[this.turn],o=this.balls[this.croquetTarget];b.x=o.x+Math.sin(angle)*.28001;b.z=o.z+Math.cos(angle)*.28001;resetHoopProgress(b);return true}
}
